class _DiffusersAdapterWrapper:
    """
    PyFunc wrapper for diffusion model adapters. Loads the base diffusion pipeline and applies
    the saved adapter weights, then exposes a ``predict`` interface that turns text prompts into
    PNG-encoded images.
    """

    def __init__(self, adapter_path: str, flavor_conf: dict, model_config: dict | None = None):
        self.adapter_path = adapter_path
        self._flavor_conf = flavor_conf
        self.model_config = model_config or {}
        self._pipeline = None

    def _load_pipeline(self):
        if self._pipeline is not None:
            return self._pipeline

        import diffusers

        base_model = self.model_config.get("base_model") or self._flavor_conf["base_model"]
        from_pretrained_kwargs = {}
        revision = self._flavor_conf.get("base_model_revision")
        if revision:
            from_pretrained_kwargs["revision"] = revision

        try:
            pipeline = diffusers.DiffusionPipeline.from_pretrained(
                base_model, **from_pretrained_kwargs
            )
        except OSError as e:
            raise MlflowException(
                f"Failed to load base model '{base_model}': {e}",
                error_code=INVALID_PARAMETER_VALUE,
            ) from e

        from mlflow.diffusers import _detect_device

        device = _detect_device()
        if device:
            try:
                pipeline = pipeline.to(device)
            except Exception as e:
                _logger.warning(f"Failed to move pipeline to device '{device}': {e}")

        adapter_type = self._flavor_conf.get("adapter_type", "lora")
        if adapter_type == "lora":
            load_kwargs = {}
            weight_name = self._flavor_conf.get("weight_name")
            if weight_name:
                load_kwargs["weight_name"] = weight_name
            pipeline.load_lora_weights(self.adapter_path, **load_kwargs)

        self._pipeline = pipeline
        return pipeline

    def get_raw_model(self):
        """Returns the underlying diffusion pipeline."""
        return self._load_pipeline()

    def _extract_prompts(self, data) -> list:
        if isinstance(data, str):
            prompts = [data]
        elif isinstance(data, list):
            prompts = list(data)
        elif isinstance(data, dict):
            if "prompt" not in data:
                raise MlflowException(
                    "Input dictionary must contain a 'prompt' key.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
            value = data["prompt"]
            if isinstance(value, str):
                prompts = [value]
            elif isinstance(value, list):
                prompts = list(value)
            else:
                raise MlflowException(
                    "The 'prompt' value must be a string or list of strings.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
        elif isinstance(data, pd.DataFrame):
            if "prompt" in data.columns:
                prompts = data["prompt"].tolist()
            elif data.shape[1] == 1:
                prompts = data.iloc[:, 0].tolist()
            else:
                raise MlflowException(
                    "Input DataFrame must contain a 'prompt' column.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
        else:
            raise MlflowException(
                f"Unsupported input type: {type(data)}. Expected a string, list of strings, "
                "dict with a 'prompt' key, or a pandas DataFrame.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if len(prompts) == 0:
            raise MlflowException(
                "No prompts provided for inference.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if any(p is None for p in prompts):
            raise MlflowException(
                "Prompt values must be strings, not None.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        return prompts

    @staticmethod
    def _image_to_png_bytes(image) -> bytes:
        if isinstance(image, (bytes, bytearray)):
            return bytes(image)
        buffer = io.BytesIO()
        image.save(buffer, format="PNG")
        return buffer.getvalue()

    def predict(self, data, params: dict[str, Any] | None = None) -> list[bytes]:
        prompts = self._extract_prompts(data)
        pipeline = self._load_pipeline()

        call_kwargs = dict(params) if params else {}
        output = pipeline(prompt=prompts, **call_kwargs)

        images = getattr(output, "images", None)
        if images is None and isinstance(output, dict):
            images = output.get("images")

        if not images:
            raise MlflowException(
                "Pipeline returned no images.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        return [self._image_to_png_bytes(image) for image in images]
